+            )}
+
+            {/* 페이지네이션 */}
+            {images.length > 1 && (
+              <Pagination>
+                {images.map((_, index) => (
+                  <PaginationDot
+                    key={index}
+                    $isActive={index === modalIndex}
+                    onClick={() => goToSlide(index)}
+                  />
+                ))}
+              </Pagination>
+            )}
+
+            {/* 닫기 버튼 */}
+            <CloseButton onClick={closeModal}>
+              ×
+            </CloseButton>
+          </ModalContainer>
+        </FullScreenModal>
+      )}
+    </>
   );
 };

 export default ImageGrid;

