import React from 'react';
import styled from 'styled-components';
import { ImageData } from '@/store/chatStore';

interface ImageGridProps {
  images: ImageData[];
  maxImages?: number;
}

const GridContainer = styled.div<{ imageCount: number }>`
  display: grid;
  gap: 8px;
  margin-bottom: 12px;
  border-radius: 12px;
  overflow: hidden;
  max-width: 320px;

  grid-template-columns: ${({ imageCount }) => {
    if (imageCount === 1) return '1fr';
    if (imageCount === 2) return '1fr 1fr';
    return '1fr 1fr 1fr'; // 3개 이상일 때
  }};

  grid-template-rows: ${({ imageCount }) => {
    if (imageCount <= 3) return '1fr';
    return '1fr 1fr'; // 4개 이상일 때는 2줄
  }};
`;

const ImageContainer = styled.div<{ isFirst?: boolean; imageCount: number }>`
  position: relative;
  overflow: hidden;
  border-radius: 8px;
  aspect-ratio: 1;

  ${({ isFirst, imageCount }) => 
    isFirst && imageCount === 3 && `
      grid-row: 1 / 3;
      aspect-ratio: 1 / 2;
    `
  }
`;

const Image = styled.img`
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.2s ease;

  &:hover {
    transform: scale(1.05);
  }
`;

const MoreIndicator = styled.div`
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.6);
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  font-weight: bold;
  backdrop-filter: blur(2px);
`;

const ImageGrid: React.FC<ImageGridProps> = ({ images, maxImages = 3 }) => {
  if (!images || images.length === 0) return null;

  const displayImages = images.slice(0, maxImages);
  const remainingCount = images.length - maxImages;

  const handleImageError = (e: React.SyntheticEvent<HTMLImageElement>) => {
    console.error('이미지 로드 실패:', e.currentTarget.src);
    // 기본 이미지로 대체하거나 에러 처리
    e.currentTarget.style.display = 'none';
  };

  return (
    <GridContainer imageCount={displayImages.length}>
      {displayImages.map((image, index) => (
        <ImageContainer 
          key={index} 
          isFirst={index === 0}
          imageCount={displayImages.length}
        >
          <Image
            src={image.url}
            alt={image.fileName || `이미지 ${index + 1}`}
            onError={handleImageError}
            loading="lazy"
          />
          {/* 마지막 이미지에 남은 개수 표시 */}
          {index === maxImages - 1 && remainingCount > 0 && (
            <MoreIndicator>
              +{remainingCount}
            </MoreIndicator>
          )}
        </ImageContainer>
      ))}
    </GridContainer>
  );
};

export default ImageGrid;
